'use strict';
const SeenHub=(()=>{
 const id=crypto.randomUUID(),peers=new Map(),reduceMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;let local={scene:'lobby',x:9.4,y:4.5,heading:-Math.PI/2,posture:0,jump:0},channel,client,connected=false,lastSent=0,lastNpc=0,revision=0,lastPacket='',commentRefresh=null,commentTimer,roomName='lobby',entered=false;
 const text=(tag,content,className)=>{const e=document.createElement(tag);e.textContent=content;if(className)e.className=className;return e};
 let name;try{name=localStorage.getItem('seen-name')}catch{}name=(name||'Guest '+id.slice(0,4)).slice(0,32);
 const badge=text('div','WELCOME','community-badge');badge.setAttribute('role','status');document.querySelector('.site-header').append(badge);
 const npcOverrides=new Map(),seatRequests=new Map(),npcWalkPositions=new Map(),npcWalkTimes=new Map(),talkingNpcs=new Map();let lastIncoming=0;
 const npcDefs={lobby:[{x:5.1,y:5.95,depth:9.8,name:'Mia',uniform:'tickets',color:'#a84635'},{x:15.6,y:6.65,name:'Leo',uniform:'popcorn',color:'#a84635',depth:19.9},{x:10.2,y:7.25,posture:1,name:'Sam',color:'#7b648d'},{x:2.3,y:3.5,name:'Alex',color:'#477e72',walk:1},{x:14,y:4.7,name:'Jamie',color:'#ac6571',walk:-1}],arcade:[{x:7,y:5,name:'Robin',color:'#c89650',walk:1}],screening:[{x:2.46,y:5.62,posture:1,name:'Taylor',color:'#687e9b'},{x:8.74,y:6.92,posture:1,name:'Casey',color:'#8c7396'},{x:4.02,y:8.22,posture:1,name:'Morgan',color:'#7b9868'}]};
 function walkX(n,i,scene,now){if(!n.walk)return n.x;const key=scene+':'+i,target=n.x+Math.sin(now*.8+i)*.65,prior=npcWalkPositions.get(key)??target;const elapsed=Math.min(.05,Math.max(0,now-(npcWalkTimes.get(key)??now)));npcWalkTimes.set(key,now);let next=prior+Math.max(-elapsed*.85,Math.min(elapsed*.85,target-prior));if(local.scene===scene&&Math.abs(n.y-local.y)<.52){const nearest=Math.max(Math.min(prior,next),Math.min(Math.max(prior,next),local.x));if(Math.hypot(nearest-local.x,n.y-local.y)<.52)next=prior}npcWalkPositions.set(key,next);return next}
 function people(scene){const now=reduceMotion?0:performance.now()/1000;return[...(npcDefs[scene.startsWith('screen-')?'screening':scene]||[]).map((base,i)=>{const n={...base,...npcOverrides.get(`${scene}:npc:${i}`)},held=talkingNpcs.get(`${scene}:npc:${i}`);if(held)return {...n,...held,gait:0,phase:0,npc:true,id:`${scene}:npc:${i}`};return{...n,x:walkX(n,i,scene,now),y:n.y,heading:scene.startsWith('screen-')&&n.posture?-Math.PI/2:n.walk?(Math.cos(now*.8+i)>=0?0:Math.PI):Math.PI/2,gait:!reduceMotion&&n.walk?Math.abs(Math.cos(now*.8+i))*.85:0,phase:now*7.5,depth:n.depth??n.x+n.y-(n.posture?.10:0),npc:true,id:`${scene}:npc:${i}`}}),...[...peers.values()].filter(v=>v.scene===scene).map(v=>({...v,heading:scene.startsWith('screen-')&&v.posture>.5?-Math.PI/2:v.heading,phase:now*5,gait:v.moving?.7:0,npc:false}))]}
 function holdNpc(person){if(!person?.npc)return;talkingNpcs.set(person.id,{x:person.x,y:person.y,heading:person.posture?person.heading:Math.atan2(local.y-person.y,local.x-person.x)});revision++}
 function releaseNpc(id){if(!id)return;talkingNpcs.delete(id);const parts=id.split(':');npcWalkTimes.set(parts[0]+':'+parts[2],performance.now()/1000);revision++}
 function badgeUpdate(){badge.textContent=!entered?'WELCOME':connected?`${peers.size+1} LIVE · NPC HOSTS`:'OFFLINE · NPC HOSTS';badge.dataset.connected=String(connected)}
 function valid(v){return v&&typeof v.id==='string'&&v.id.length<=50&&typeof v.scene==='string'&&/^(lobby|arcade|screen-0[1-4])$/.test(v.scene)&&['x','y','heading','posture','jump'].every(k=>Number.isFinite(v[k]))&&v.x>=0&&v.x<=19&&v.y>=0&&v.y<=12&&v.jump>=0&&v.jump<2&&v.posture>=0&&v.posture<=1&&Math.abs(v.heading)<100&&typeof v.name==='string'}
 function receive(v){if(!valid(v)||v.id===id)return;peers.set(v.id,{...v,name:v.name.slice(0,32),at:Date.now()});revision++}
 function publish(state){local={...local,...state};const now=performance.now(),packet=JSON.stringify(local);if(!reduceMotion&&now-lastNpc>120){revision++;lastNpc=now}if(roomName!==local.scene){roomName=local.scene;audioRoom(roomName);if(connected)channel.track({id,name,...local}).catch(()=>{})}if(!connected||now-lastSent<120||packet===lastPacket)return;lastSent=now;lastPacket=packet;channel.send({type:'broadcast',event:'move',payload:{...local,id,name}}).catch(()=>{});if(roomName!==local.scene){roomName=local.scene;channel.track({id,name,scene:roomName,...local}).catch(()=>{});audioRoom(roomName)}}
 function drawPeople({ctx,unit,project,scene}){return people(scene).map(v=>({depth:v.depth??v.x+v.y-(v.posture?.1:0),paint:()=>drawSeenCharacter({ctx,unit,project,x:v.x,y:v.y,heading:v.heading||0,posture:v.posture||0,jump:v.jump||0,gait:v.gait||0,phase:v.phase||0,nameTag:v.npc?(Math.hypot(v.x-local.x,v.y-local.y)<2.3?v.name:''):v.name,nameKind:v.npc?'npc':'live',shirtColor:v.color||'#5f8db7',uniform:v.uniform,tagColor:v.npc?'#a1a58b':'#e9d5aa'})}))}
 async function connect(){try{const config=window.SEEN_COMMUNITY;if(!config?.url||!window.supabase)throw Error('No backend');client=supabase.createClient(config.url,config.key,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false},realtime:{params:{eventsPerSecond:10}}});channel=client.channel('seen-cinema-v1',{config:{presence:{key:id},broadcast:{self:false}}});channel.on('presence',{event:'sync'},()=>{const live=new Set();for(const arr of Object.values(channel.presenceState()))for(const v of arr){live.add(v.id);if(!peers.has(v.id))receive(v)}for(const key of peers.keys())if(!live.has(key))peers.delete(key);badgeUpdate();revision++;if(connected)channel.send({type:'broadcast',event:'move',payload:{...local,id,name}}).catch(()=>{})}).on('broadcast',{event:'move'},({payload})=>receive(payload)).on('broadcast',{event:'comment'},()=>{clearTimeout(commentTimer);commentTimer=setTimeout(()=>commentRefresh?.(),800)}).on('broadcast',{event:'seat_request'},({payload:r})=>{if(!r||r.to!==id||!peers.has(r.from)||r.scene!==local.scene||typeof r.requestId!=='string'||r.requestId.length>60||!/^[ABCDE]0?[1-9]$|^[ABCDE]10$/.test(r.seatId)||Date.now()-lastIncoming<5000)return;lastIncoming=Date.now();document.dispatchEvent(new CustomEvent('seen-seat-request',{detail:{...r,name:peers.get(r.from).name}}))}).on('broadcast',{event:'seat_reply'},({payload:r})=>{const pending=r&&seatRequests.get(r.requestId);if(!pending||r.to!==id||r.from!==pending.to||typeof r.yes!=='boolean')return;clearTimeout(pending.timer);seatRequests.delete(r.requestId);pending.resolve(r.yes)}).subscribe(status=>{connected=status==='SUBSCRIBED';if(!connected){peers.clear();revision++}badgeUpdate();if(connected)channel.track({id,name,...local}).catch(()=>{})})}catch{connected=false;badgeUpdate()}}
 async function mountComments(container,articleId){container.querySelector('.article-comments')?.remove();const section=document.createElement('section');section.className='article-comments';section.setAttribute('aria-label','Reader comments');section.append(text('span','AFTER THE CREDITS','comments-kicker'),text('h3','Keep the conversation going.'));const list=document.createElement('div');list.className='comment-list';list.setAttribute('aria-live','polite');list.append(text('p','Loading comments…','comments-empty'));const form=document.createElement('form');form.className='comment-form';form.innerHTML='<label>Your name<input name="author" maxlength="32" required autocomplete="nickname"></label><label>What stayed with you?<textarea name="body" minlength="2" maxlength="800" rows="3" required placeholder="Share a thought about the article…"></textarea></label><small>Public comments · Be kind · No links or personal information.</small><button type="submit">POST COMMENT ↗</button>';form.elements.author.value=name;const status=text('p','','comment-status');status.setAttribute('role','status');section.append(list,form,status);container.append(section);let refreshing=false;
 async function refresh(){if(refreshing||!section.isConnected)return;refreshing=true;try{if(!client)throw Error();const {data,error}=await client.from('seen_comments').select('id,author,body,created_at').eq('article_id',articleId).order('created_at',{ascending:false}).limit(50);if(error)throw error;list.replaceChildren();if(!data.length)list.append(text('p','No comments yet. Start the conversation.','comments-empty'));for(const row of data){const item=document.createElement('article');item.className='reader-comment';item.append(text('strong',row.author),text('time',new Date(row.created_at).toLocaleDateString('en-US',{month:'short',day:'numeric'})),text('p',row.body));list.append(item)}}catch{list.replaceChildren(text('p','Comments could not load. Try again in a moment.','comments-empty'))}finally{refreshing=false}}
 commentRefresh=refresh;form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button'),body=form.elements.body.value.trim(),author=form.elements.author.value.trim();if(body.length<2||!author)return;if(/https?:\/\/|www\./i.test(body)){status.textContent='Please share your thoughts without links.';return}button.disabled=true;status.textContent='Posting…';try{if(!client)throw Error();let visitor;try{visitor=localStorage.getItem('seen-comment-visitor');if(!visitor){visitor=crypto.randomUUID();localStorage.setItem('seen-comment-visitor',visitor)}}catch{visitor=id}const {error}=await client.from('seen_comments').insert({article_id:articleId,visitor_id:visitor,author,body});if(error)throw error;name=author;try{localStorage.setItem('seen-name',name)}catch{}form.elements.body.value='';status.textContent='Posted. Thank you for joining the conversation.';await refresh();channel?.send({type:'broadcast',event:'comment',payload:{article:articleId}});channel?.track({id,name,...local});fx('correct')}catch(error){status.textContent=error?.code==='P0001'?'Please wait 30 seconds before posting again.':'Could not post. Your text is still here; please try again.'}finally{button.disabled=false}};await refresh()}
 // All audio is synthesized locally; playback starts only from the sound button.
 const soundButton=text('button','SOUND OFF','sound-toggle');soundButton.type='button';soundButton.setAttribute('aria-pressed','false');document.querySelector('.site-header').append(soundButton,document.querySelector('#index-toggle'));let audio,master,nodes=[],musicTimer,soundOn=false;
 function tone(freq,duration=.14,type='sine',volume=.045){if(!soundOn||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+duration);o.connect(g).connect(master);o.start();o.stop(audio.currentTime+duration)}
 function fx(kind){if(kind==='correct'){tone(523,.13);setTimeout(()=>tone(784,.22),100)}else if(kind==='wrong')tone(160,.22,'triangle');else if(kind==='jump')tone(440,.1,'sine',.025)}
 function audioRoom(scene){if(!soundOn)return;clearInterval(musicTimer);for(const n of nodes){try{n.stop()}catch{}}nodes=[];const screening=scene.startsWith('screen-'),arcade=scene==='arcade';const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=screening?55:arcade?110:82.4;g.gain.value=screening?.02:.008;o.connect(g).connect(master);o.start();nodes.push(o);let beat=0;musicTimer=setInterval(()=>{if(document.hidden||document.querySelector('dialog[open]'))return;const notes=arcade?[262,330,392,523,392,330]:[220,277,330,277];tone(notes[beat++%notes.length],arcade?.18:.7,arcade?'triangle':'sine',arcade?.018:.009)},arcade?480:2200)}
 soundButton.onclick=async()=>{try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.gain.value=.55;master.connect(audio.destination)}await audio.resume();soundOn=!soundOn;soundButton.textContent=soundOn?'SOUND ON':'SOUND OFF';soundButton.setAttribute('aria-pressed',String(soundOn));if(soundOn)audioRoom(local.scene);else{clearInterval(musicTimer);for(const n of nodes){try{n.stop()}catch{}}nodes=[]}}catch{soundButton.textContent='SOUND UNAVAILABLE'}};
 document.addEventListener('visibilitychange',()=>{if(audio){if(document.hidden)audio.suspend();else if(soundOn)audio.resume()}});new MutationObserver(()=>{if(master&&audio)master.gain.setTargetAtTime(document.querySelector('dialog[open]')?.20:.55,audio.currentTime,.15)}).observe(document.body,{subtree:true,attributes:true,attributeFilter:['open']});

 const nameHitContext=document.createElement('canvas').getContext('2d');
 function hitPerson({scene,project,unit,px,py}){const width=document.getElementById(scene==='lobby'?'world':scene==='arcade'?'arcade-world':'room-world').clientWidth;return [...people(scene)].sort((a,b)=>(b.x+b.y)-(a.x+a.y)).find(v=>{const blend=v.posture||0,jump=v.jump||0,foot=project(v.x,v.y,jump),head=project(v.x,v.y,1.49-.12*blend+jump);if(Math.abs(px-foot.x)<Math.max(10,unit*.32)&&py>=head.y-3&&py<=foot.y+3)return true;if(v.npc&&Math.hypot(v.x-local.x,v.y-local.y)>=2.3)return false;const size=v.npc?Math.max(8,Math.min(11,unit*.19)):Math.max(11,Math.min(15,unit*.27));nameHitContext.font=`600 ${size}px "DM Sans",sans-serif`;const tag=project(v.x,v.y,1.67-.12*blend+jump),w=Math.min(180,nameHitContext.measureText(v.name).width)+14,h=size+10,x=Math.max(w/2+3,Math.min(width-w/2-3,tag.x));return px>=x-w/2-4&&px<=x+w/2+4&&py>=tag.y-h-4&&py<=tag.y+4})}

 function relocateNpc(person,scene,seat){npcOverrides.set(person.id,{x:seat.x+.33,y:seat.y+.22,posture:1,walk:0});revision++}
 function requestSeat(person,{scene,seatId}){if(!connected)return Promise.resolve(null);const requestId=crypto.randomUUID();return new Promise(resolve=>{const timer=setTimeout(()=>{seatRequests.delete(requestId);resolve(null)},20000);seatRequests.set(requestId,{to:person.id,resolve,timer});channel.send({type:'broadcast',event:'seat_request',payload:{requestId,from:id,to:person.id,name,scene,seatId}}).catch(()=>{clearTimeout(timer);seatRequests.delete(requestId);resolve(null)})})}
 function replySeat(req,yes){channel?.send({type:'broadcast',event:'seat_reply',payload:{requestId:req.requestId,from:id,to:req.from,yes}}).catch(()=>{})}
 function join(nickname){name=nickname;entered=true;revision++;try{localStorage.setItem('seen-name',name)}catch{}badge.textContent='CONNECTING…';connect()}
 return{publish,drawPeople,mountComments,fx,people,join,holdNpc,releaseNpc,hitPerson,relocateNpc,requestSeat,replySeat,get name(){return name},get entered(){return entered},get revision(){return revision},get peers(){return [...peers.values()]},get connected(){return connected}};
})();
